/* Sentience layer for scripts/thrive.mjs — imported as P6.
 * Edit here or in thrive.mjs categories; then run: node scripts/thrive.mjs
 */
export const P6 = [
/* ----------------------------------------------------------- sentience -- */
{c:'sentience',t:'Name the three modes and refuse a fourth',g:'planetclaim',d:'Survivorship, tutorial-feedback, and an explicitly fictional planetary mind. `W.gaiaMode` already holds the first two. A fourth — a mind that is implied but not labelled — is how the product would lose the argument Lovelock actually won. The switch is a ruleset flag and a sentence in the HUD, and it has to be on before any voice, face or drive is allowed to sound like intent.',k:'MODEL',e:'S',i:3},
{c:'sentience',t:'A mind is four parts, the same four a being gets',n:['planetclaim','drivevec'],d:'Perception, drives, memory, action. `gaiaTick` is perception; the missing drive vector is this backlog; memory is the climate record nobody keeps; action is the god verbs. Writing "sentient" without those four is drawing a face on a thermostat, which is what `gaiaPolicyTick` already is.',k:'MODEL',e:'M',i:3},
{c:'sentience',t:'Distributed regulation is not a mind',n:['planetclaim'],d:'Daisyworld regulates because black and white daisies have different temperature optima, not because anything decides. Presenting that as sentience is the exact confusion the tutorial exists to prevent. Keep Daisyworld as the proof that regulation needs no foresight, and keep the fictional mind in a different ruleset so they cannot be mistaken for each other.',k:'MODEL',e:'S',i:3},
{c:'sentience',t:'Autopilot is a player, not a planet',n:['planetclaim','gaiapolicy'],d:'`W.autopilot` is a checkbox that acts with god verbs. That is a gardener-on-rails, and it is a good mode. It is not the biosphere waking up. The interface has to say *you handed the tools to a script*, or players will believe the daisies learned to work the solar slider.',k:'PLAY',e:'S',i:3},
{c:'sentience',t:'The fiction switch, on the world, in the save',n:['planetclaim'],d:'A planetary mind is a property of a run, stored next to `autopilot`, visible on the shelf entry, and stripped from any scenario that claims to be a science result. `shelfEntryFromWorld` already stores `disequilibrium`; storing the claim is the same field.',k:'MODEL',e:'S',i:3},
{c:'sentience',t:'Four minds can share one sphere',n:['planetclaim'],d:'The biosphere (survivorship), the civilisation (`notice.js`), the player, and the autopilot. They have different sensors, different timescales and different verbs. The interesting game is the argument between them, and today only the player has a body.',k:'PLAY',e:'M',i:3},
{c:'sentience',t:'When the civ becomes the planet\'s cortex',n:['planetclaim','bandtociv'],d:'A scientific civilisation with a carbon model is a planetary mind made of people. SimEarth\'s late game was this. `civ.worship === \'scientific\'` is a string assigned from a style heuristic; it should be the start of a control loop that competes with Gaia rather than a flavour label.',k:'MODEL',e:'L',i:3},
{c:'sentience',t:'Superorganism versus organism, stated',n:['planetclaim'],d:'A reef colony, an ant nest, a planet. The group record this backlog already asks for is the same object at three scales. Write down which scale is allowed to have a drive vector, or every mat will get a hunger and the word will mean nothing.',k:'MODEL',e:'S',i:3},
{c:'sentience',t:'A being that is the whole sphere',n:['planetclaim','pdrive'],d:'One ENT-shaped record for the planet: energy as the free-energy disequilibrium, cell as undefined, lineage as the tree, name as the world\'s. Inspecting the planet with the same panel as a creature is the joke that teaches the architecture, and it is also a real debug view of the controller.',k:'SHOW',e:'M',i:2},
{c:'sentience',t:'Sentience as inhabitance of the control loop',n:['planetclaim'],d:'`W.inhabitance` is meanLife × 1.2. A better split: inhabitance is biomass, sentience-mode inhabitance is whether anything is actually closing a loop. A green sterile-looking desert of cyanobacteria can regulate; a lush world with the controller off and the tips unconnected cannot.',k:'MODEL',e:'M',i:3},
{c:'sentience',t:'The hard problem is a glossary page',n:['planetclaim'],d:'`glossary.js` already carries definitions. Cognition is where a simulation most easily overclaims. The page says what is modelled (a controller), what is presented (a voice, a face), and what is not claimed (phenomenal experience). Same honesty the provenance tags apply to materials.',k:'PROVE',e:'S',i:3},
{c:'sentience',t:'Watson and Lovelock never claimed a mind',n:['planetclaim'],d:'The original Daisyworld paper is a proof about feedback, and the product owns a working Daisyworld. Quote it in the tutorial, then show the fictional mode as a separate toy. Borrowing their authority for a talking planet is the one way to make the science layer look like marketing.',k:'PROVE',e:'S',i:3},
{c:'sentience',t:'A planet that can be wrong about itself',n:['planetclaim','pdrive'],d:'Acting on a stale memory — raising solar because last era was cold, fighting an AMOC that already recovered — is the difference between a lookup and a mind. `W._prevMeanTemp` is the entire climate memory today. A ring buffer of a few eras is the cheapest possible inner life.',k:'MODEL',e:'M',i:3},
{c:'sentience',t:'Death of a mind',n:['planetclaim'],d:'Snowball, moist-greenhouse and sterilising impact already set `W.state`. The fictional mind should go quiet with them: no voice, no face, `gaiaMode = \'gone\'`. A corpse that keeps chatting is a worse fiction than a silent rock.',k:'SHOW',e:'S',i:3},
{c:'sentience',t:'Information that is actually integrated',n:['planetclaim'],d:'Seven tipping elements, a carbon vector, a tree, a disequilibrium scalar. A cheap integration score — how many of those streams are coupled this tick — is a better "how awake is this planet" meter than `W.health`, and it uses no new physics.',k:'MODEL',e:'M',i:2},
{c:'sentience',t:'A mind that thinks in Myr cannot talk in seconds',n:['planetclaim','biotime'],d:'Weathering answers in 100 kyr. A sentence every frame about what Gaia "wants" is lying about timescale. Voice rate has to track the biology clock, or the planet sounds frantic on a world whose only move this century is a millimetre of soil.',k:'SHOW',e:'M',i:3},
{c:'sentience',t:'Do not call Daisyworld sentient',n:['planetclaim'],d:'`gaiaMode = \'tutorial-feedback\'` is already the right label. Guard the voice, the face and the drive vector behind `gaiaMode === \'mind\'` (or whatever the flag is named), and assert Daisyworld never emits a sentence of intent.',k:'PROVE',e:'S',i:3},
{c:'sentience',t:'The label has to match the mechanism',n:['planetclaim'],d:'If the HUD says mind, the controller must be reading more than two scalars and acting through verbs. If it says survivorship, no voice of intent. Assert the pairing, because a mismatched label is how this feature becomes an embarrassment rather than a mode.',k:'PROVE',e:'S',i:3},
{c:'sentience',t:'Kirchner on a switch',n:['planetclaim'],d:'A scenario toggle that kills the biosphere and keeps the geology, so the player can see which part of the temperature path was life. That experiment is the whole debate, and `W.life` can already be zeroed. The missing piece is the before/after and a sentence that does not editorialize the result.',k:'PLAY',e:'M',i:3},
{c:'sentience',t:'A run that is allowed to stay a rock',n:['planetclaim'],d:'Most catalogue worlds should never wake. The default is silence. Sentience is a rare, expensive, labelled event — the same rarity argument this backlog already makes for brains in animals. If every sphere talks, none of them are a planet.',k:'PLAY',e:'S',i:3},

/* -------------------------------------------------------------- pdrive -- */
{c:'pdrive',t:'A drive vector for the planet',g:'pdrive',n:['gaiapolicy','planetclaim'],d:'Hunger, heat, cold, fear (tip proximity), pain (`rateStress`), crowding (inhabitance vs habitability), Medea. Continuous, decaying, discharged by verbs. This is `drivevec` at radius 6,370 km, and it is what lets the four if-statements die without being replaced by a larger pile of if-statements.',k:'MODEL',e:'M',i:3},
{c:'pdrive',t:'Hunger is whatever is limiting',n:['pdrive'],d:'Light, water, phosphate, nitrogen, carbon, space. The model computes each per cell and never says which is binding. The loudest planetary hunger is that binding constraint, averaged with a stated rule, and it is the sentence a metabolism would actually utter.',k:'MODEL',e:'M',i:3},
{c:'pdrive',t:'Pain is rate stress',n:['pdrive'],d:'`W.rateStress` already exists from dT/dt. Map it onto a drive and a fast anthropogenic pulse hurts more than a slow Milankovitch one, which is the published reason ecosystems die of speed rather than of climate. No new field.',k:'MODEL',e:'S',i:3},
{c:'pdrive',t:'Fear is tipping proximity',n:['pdrive','tipgeo'],d:'Distance-to-threshold on each `TIPPING` row, the nearest one the loudest. A controller that is afraid of the Amazon and not of the AMOC is a controller that has a geography, which is the whole point of treating tips as places.',k:'MODEL',e:'M',i:3},
{c:'pdrive',t:'Heat and cold, still, but not as the whole mind',n:['pdrive'],d:'The current four ifs are two drives. Keep them as the loudest pair — temperature is the variable Daisyworld was built to regulate — and stop letting them drown carbon, ice, diversity and disequilibrium.',k:'MODEL',e:'S',i:3},
{c:'pdrive',t:'Perception is the state vector, named',n:['pdrive'],d:'meanTemp, iceFrac, gases, carbon fluxes, tips, disequilibrium, resilience, inhabitance, habitability, medeaScore, dTempDt. Write it as a struct the controller reads and the inspect panel prints. Today those numbers live on `W` and the policy peeks at two of them.',k:'MODEL',e:'S',i:3},
{c:'pdrive',t:'Memory of climates, a ring of eras',n:['pdrive'],d:'`W._prevMeanTemp` is one float. Keep a small ring — last season, last century, last glacial, last burial pulse — so the planet can return to a place, fear a place, and be wrong about a place. Same shape as the being memory item, same byte argument.',k:'MODEL',e:'M',i:3},
{c:'pdrive',t:'Attention: which basin is in trouble',n:['pdrive','tipgeo'],d:'A being tracks a few things, not everything in range. The planet should track a few regions — the dying forest, the stalled conveyor, the bleaching reef — and put the camera and the verbs there. `shouldHaltFF` already stops for anomalies; this is the same idea aimed at organs.',k:'MODEL',e:'M',i:3},
{c:'pdrive',t:'Actuators are the god verbs, all of them',n:['pdrive'],d:'Solar, CO₂, albedo paint, aerosol, seed, refuge, trip conveyor, local weather, magnetosphere. `gaiaPolicyTick` uses two. A mind with two muscles is a neck. The budget and the receipts already price the rest.',k:'MODEL',e:'M',i:3},
{c:'pdrive',t:'Cannot think every tick',n:['pdrive'],d:'`forkRun` and `forecastAct` are expensive. Planetary deliberation is every N years of `dtYr`, with a stated staleness, the way beings get LOD. A mind that re-plans at 60 Hz on a 10 kyr tick is the same bug as agents on the render loop.',k:'MODEL',e:'M',i:3},
{c:'pdrive',t:'The same utility scorer as a being',n:['pdrive','utility'],d:'Candidate verbs scored against drives, pick the best that the budget allows. One mechanism, two scales. If the planetary scorer is a new pile of thresholds, the architecture thesis of this backlog is decoration.',k:'MODEL',e:'M',i:3},
{c:'pdrive',t:'Explain a planetary decision',n:['pdrive','explainai'],d:'Click the planet: these were the drives, these were the candidate verbs and their scores, this is what it chose, this is what it expected, this is what happened. `W.gaiaLog` currently stores `{ t, acts }` strings. Replace the string with the score row.',k:'SHOW',e:'M',i:3},
{c:'pdrive',t:'A temperament for a world',n:['pdrive'],d:'Gardener, regulator, experimenter, Medea — the dispositions already named in gaiamind — as a weighting of the same drives, stored on the ruleset, visible on the catalogue card. Different worlds wake differently, which is the point of having 120 of them.',k:'PLAY',e:'M',i:3},
{c:'pdrive',t:'Thinking costs energy',n:['pdrive'],d:'`thermoCost` already prices tools. Forking a run to look ahead should cost more than a reflex nudge. A mind that plans for free will always plan, which is not how metabolisms work and not how this economy was designed.',k:'MODEL',e:'S',i:3},
{c:'pdrive',t:'LOD: coarse when the player is on the ground',n:['pdrive'],d:'Full deliberation at orbit, a slow pulse at regional, frozen when the player is inside a tile watching a hunt. The interesting event at ground scale is the animal; a planet muttering about CO₂ over it is the wrong narrator.',k:'MODEL',e:'M',i:2},
{c:'pdrive',t:'Determinism, same stream',n:['pdrive'],d:'`rngOf(W, \'rngGod\')` already serves notice and prayers. Planetary policy uses that stream or a dedicated `rngGaia`, never `Math.random`, or the fork, the save and the catalogue experiment all break.',k:'PROVE',e:'S',i:3},
{c:'pdrive',t:'Save the planetary policy',n:['pdrive','entsave'],d:'Drive weights, memory ring, current attention, last decision. `serializeRun` is at version 5. A reload that forgets why the planet was raising solar is a reload that breaks the character.',k:'MODEL',e:'S',i:3},
{c:'pdrive',t:'Assert drives change with forcing',n:['pdrive'],d:'Pulse freshwater, fear of AMOC should rise. Dim the sun, cold should rise. If the vector is static under a stated forcing, it is a skin on the four ifs and this category has failed.',k:'PROVE',e:'M',i:3},
{c:'pdrive',t:'Delete the four if-statements when this ships',n:['pdrive'],d:'The end state is that `gaiaPolicyTick` no longer exists as four thresholds. Same deletion test this backlog already applies to `pickBehav`. If the function is still there wrapped, the mind did not land.',k:'MODEL',e:'M',i:3},
{c:'pdrive',t:'A millisecond budget for the planet',n:['pdrive','entbudget'],d:'One scorer, a handful of forecasts, no per-cell loop. State the cost and assert it. Planetary thought that scans `NC` to "feel" is how the 12 ms budget dies, and `gaiaTick` already did the reduction to scalars.',k:'PROVE',e:'S',i:3},

/* --------------------------------------------------------------- metab -- */
{c:'metab',t:'Show carbon breathing as a pulse on the land',g:'metab',n:['gaiaface'],d:'The Keeling curve is the inhale of the north. `nppField` already has a phenology term from `W.season` and latitude. A subtle darkening of northern green in summer and a browning in winter is the same pulse. Do not make it neon; make it true. That pulse is the first proof the planet is a metabolism rather than a texture.',k:'SHOW',e:'M',i:3},
{c:'metab',t:'Albedo as the clothing the planet puts on',n:['metab'],d:'Ice, cloud, canopy, desert, daisy bands, `albedoPaint`. The controller already wants to raise and lower temperature; clothing is how a real Gaia would do it, and `paintAlbedo` is already a god verb. Draw the Bond albedo as a disc average next to the face so a white world is a choice you can see.',k:'SHOW',e:'M',i:3},
{c:'metab',t:'Ice–albedo as a visible runaway, not a floor',n:['metab','homeo'],d:'`iceTick` floors `iceLand` above 0.86 and `iceSea` above 0.88 so the caps cannot die. A snowball should be a thing you watch: white grows, albedo rises, white grows. The clamp hides the most famous Gaia story and it makes a sentient planet unable to freeze itself.',k:'MODEL',e:'M',i:3},
{c:'metab',t:'Weathering as a slow green-to-pale of mountains',n:['metab','homeo'],d:'The Walker thermostat is a CO₂ leak from warm wet land. The picture is mountains going dull and rivers going milky. If CO₂ drops with no change on the ground, the thermostat is a cheat code and the metabolism is off-screen.',k:'SHOW',e:'M',i:2},
{c:'metab',t:'Oxygen as a colour of the sky, late',n:['metab'],d:'Ozone from O₂ is why twilight is blue. Deep time should have a pale, ozone-poor limb until the GOE, then the ring appears. That is Gaia as a history of the photograph, and `uOzone` is already a mix factor waiting to be a real absorption.',k:'SHOW',e:'M',i:3},
{c:'metab',t:'Disequilibrium as the living smell',n:['metab'],d:'`W.disequilibrium = sqrt(O2 × CH4) × 200`. Plot it, speak it, colour a thin limb with it. A world that is chemically at equilibrium is a world that has stopped fighting, which is the honest synonym for dead.',k:'SHOW',e:'S',i:3},
{c:'metab',t:'NPP as the heartbeat on the disc',n:['metab'],d:'`W.npp` is per cell and the overlay exists. Animate it as a slow glow whose integral is the pulse, not as a static false-colour. A heartbeat you can count is how a child reads a body; the same trick works on a planet.',k:'SHOW',e:'M',i:3},
{c:'metab',t:'Cloud as a thermostat the player can see',n:['metab'],d:'Clouds raise albedo and they are already a field. A controller that seeds clouds (`seedClouds` exists) should leave a visible deck, and a world cooling by cloud should go milky from orbit, not just drop a number.',k:'SHOW',e:'M',i:2},
{c:'metab',t:'Dust as a fever',n:['metab'],d:'`gases.dust` and the dust storm path already exist. A planet fighting heat with haze should look sick — brown, dim, the sun a smeared disc — because that is what a fever looks like from outside.',k:'SHOW',e:'M',i:2},
{c:'metab',t:'The anti-greenhouse haze as a veil with a cause',n:['metab'],d:'`hazeAntiGreenhouse` reddens and cools. Titan and Archean Earth should go orange for a reason you can point at: a photochemical haze that also changes the limb. The veil is the metabolism, not a tint.',k:'SHOW',e:'M',i:2},
{c:'metab',t:'Draw the carbon budget on the planet',n:['metab'],d:'In, out, burial, outgassing, player injection. `W.carbon` has fluxes. A small Sankey or a pair of opposing arrows on the Lab Gaia card is the difference between a health number and a breathing body.',k:'SHOW',e:'M',i:3},
{c:'metab',t:'Connect `W.health` to something you can see',n:['metab','gaiaface'],d:'`health` is already in the calibrate snapshot. If it is a function of ice, life and temperature, the disc should look sick when it is low: more desert, more ice, or a bleach. A healthy number on a lime continent is the old bug.',k:'SHOW',e:'M',i:3},
{c:'metab',t:'A sick Earth should look sick in true colour first',n:['metab','gaiaface'],d:'Snowball, hothouse, anoxic — the photograph changes before the gauge. If Health is low and the disc still looks like a Blue Marble, the face is lying and the mind is a HUD.',k:'SHOW',e:'M',i:3},
{c:'metab',t:'Phosphorus as the slow pulse',n:['metab'],d:'Productivity limited by the scarcest nutrient is already an evolution-backlog item. At planetary scale it is the metabolic rate the mind cannot hurry. Show the bottleneck on the face as a long, reluctant beat, not as a missing green.',k:'MODEL',e:'M',i:2},
{c:'metab',t:'Water as blood',n:['metab'],d:'Close the water budget and the planet has a circulation the way a body has one. Sea level, ice volume, vapour and soil moisture are the reservoirs. A mind that regulates temperature while leaking water mass is a mind ignoring a haemorrhage.',k:'MODEL',e:'M',i:3},
{c:'metab',t:'Heat transport as circulation you can feel',n:['metab'],d:'The currents backlog is the cardiovascular system. AMOC is a pulse in the North Atlantic. Until that pulse is a diagnosed streamfunction, the planetary mind is claiming an organ it does not have — which this document already called a fake vital sign.',k:'MODEL',e:'L',i:3},
{c:'metab',t:'Core sampler as a metabolic history',n:['metab'],d:'The core already reads banded iron, coal, till, ejecta. Those are breaths the planet took. Labelling the layers as metabolic events — GOE, burial pulse, snowball dust — turns a geology toy into the planet\'s medical record.',k:'SHOW',e:'M',i:2},
{c:'metab',t:'Assert fluxes, not stocks',n:['metab'],d:'A face that only shows amounts cannot show breathing. Assert that the displayed pulse is a derivative of carbon or NPP, and that it moves under a seasonal forcing on a world with obliquity.',k:'PROVE',e:'M',i:3},
{c:'metab',t:'CLAW only if it earns a flux',n:['metab'],d:'Dimethyl sulphide, cloud condensation, cooling — a famous Gaia loop and an easy one to fake. Do not add a DMS slider. If marine NPP already modulates cloud, show that coupling; if it does not, say the hypothesis is off, because a sentient planet should not get free magic.',k:'PROVE',e:'M',i:2},
{c:'metab',t:'Fire as a regulator, visible',n:['metab'],d:'Fire recycles nutrients, sets albedo and caps biomass. If the model grows vegetation without a loss term that looks like fire in the dry season, the metabolism is missing an organ animals have been watching for a million years.',k:'SHOW',e:'M',i:2},

/* -------------------------------------------------------------- homeo -- */
{c:'homeo',t:'The silicate weathering thermostat, properly',g:'homeo',d:'Walker, Hays and Kasting: weathering rate rises with temperature and runoff, drawing down CO₂, on a 100 kyr–1 Myr timescale. `gaiaTick` has this as one line with a magic 0.0000004, skipped when `W.carbon` exists. Give it explicit T and runoff dependence and it becomes the negative feedback that keeps a planet habitable for four billion years — the nervous system, not a leak.',k:'MODEL',e:'M',i:3},
{c:'homeo',t:'Do not floor the ice',n:['homeo'],d:'Caps that cannot die cannot runaway. Remove the 0.86 / 0.88 floors or gate them to a tutorial, and let snowball be a reachable, reversible, hysteretic state — which `W.state` already names and `iceTick` currently forbids.',k:'MODEL',e:'M',i:3},
{c:'homeo',t:'Cloud feedback with a sign',n:['homeo'],d:'Low cloud cools, high cloud warms, and the net sign is the argument. A single translucent shell with no height cannot regulate. Typing cloud by regime is a rendering item and a homeostasis item at once; without the sign, seeding clouds is a coin flip.',k:'MODEL',e:'L',i:3},
{c:'homeo',t:'Vegetation–albedo, Charney\'s loop',n:['homeo','metab'],d:'Dry a savanna, raise albedo, dry it more. The Sahel is the textbook. Canopy already darkens land in the shader by guesswork (`greenDom`); driving albedo from cover fraction makes a desert a decision the biosphere can make and unmake.',k:'MODEL',e:'M',i:3},
{c:'homeo',t:'Oxygen is not a painted constant',n:['homeo'],d:'Photosynthesis and burial already move O₂ in the chemistry. Regulation of pO₂ — fire plus burial plus respiration — is a real debate. A planetary mind that can inject CO₂ and cannot touch oxygen is missing the gas that made animals possible.',k:'MODEL',e:'M',i:3},
{c:'homeo',t:'Two carbon timescales, both present',n:['homeo'],d:'Organic cycle fast, silicate cycle slow. A controller that only sees `gases.CO2` will use the wrong muscle. Expose both fluxes on the perception struct, or every "drew down CO₂" log line will be a lie about which reservoir moved.',k:'MODEL',e:'M',i:3},
{c:'homeo',t:'Water vapour, the fast one',n:['homeo'],d:'The strongest greenhouse gas and the one the four ifs never mention. If H₂O is tracked, the moist-greenhouse path is a feedback the mind should fear; if it is not, `W.state === \'moist-greenhouse\'` is a name without a mechanism.',k:'MODEL',e:'M',i:3},
{c:'homeo',t:'Daisyworld remains the reference experiment',n:['homeo'],d:'N species, rising sun, no atmosphere, flat world. Demote it from the catalogue to the first five minutes, then compare every later controller against it: does this world regulate for a reason you can point at, the way the daisies do?',k:'PLAY',e:'M',i:3},
{c:'homeo',t:'A world without life still has geology',n:['homeo'],d:'Weathering, ice-albedo, silicate outgassing. Assert that an abiotic twin still opposes a temperature pulse, weaker and slower. If it does not, Gaia is being asked to invent physics, which is Kirchner\'s objection made into a bug.',k:'PROVE',e:'M',i:3},
{c:'homeo',t:'Nitrogen fixation as a valve',n:['homeo'],d:'Life invented a way to unlock the air. That valve is a planetary control point with a date, a guild and an energy cost. Treat it as one, and the GOE-adjacent story gains a second act that is not oxygen.',k:'MODEL',e:'M',i:2},
{c:'homeo',t:'Methane as a young planet\'s thermostat',n:['homeo'],d:'Archean warmth is a methane problem. `gases.CH4` exists and disequilibrium already multiplies it. A faint-young-sun world that cannot raise CH₄ cannot stay liquid, and a mind that only injects CO₂ is using the wrong era\'s tool.',k:'MODEL',e:'M',i:2},
{c:'homeo',t:'Hysteresis is the lesson, not the bug',n:['homeo'],d:'Once a snowball locks, removing the cause must not undo it. The prototype reproduced this accidentally on Ares. Make it intentional, labelled on the face as a scar, and teach it in the tutorial after Daisyworld.',k:'MODEL',e:'M',i:3},
{c:'homeo',t:'Gain measured by perturbation, in the suite',n:['homeo'],d:'`W.feedbackGain` is `weatheringFlux × 20 − rateStress`. Pulse solar by a stated amount, measure dT, report the ratio. That number replaces the fitted constant and it is what "the planet is regulating" means in a lab.',k:'PROVE',e:'M',i:3},
{c:'homeo',t:'Autopilot off is the honest test of Gaia',n:['homeo'],d:'The physics must oppose a perturbation without `W.autopilot`. The fictional mind is allowed to help. Mixing the two in a screenshot is how a trailer lies. Tag every capture with the flag.',k:'PROVE',e:'S',i:3},
{c:'homeo',t:'Fire, ice, cloud, rock: name the four loops',n:['homeo'],d:'A player should be able to list the negative feedbacks this world actually has. If the list is "the autopilot", the product has failed the SimEarth thesis. A Lab card of loops with on/off and gain is the teaching.',k:'SHOW',e:'M',i:3},
{c:'homeo',t:'Assert a pulse is opposed',n:['homeo'],d:'Same seed, +CO₂, 200 ticks, controller off: temperature rise then partial return, ice loss then partial return, weathering up. If temperature steps and stays, there is no Gaia to be sentient with.',k:'PROVE',e:'M',i:3},
{c:'homeo',t:'Phosphate, the brake you cannot talk past',n:['homeo'],d:'A mind that wants more life and has no phosphate is a mind that has to wait for weathering. That wait is character. Do not let the controller spawn biomass from a slider.',k:'MODEL',e:'M',i:2},
{c:'homeo',t:'Runaway terminal states with their own faces',n:['homeo','gaiaface'],d:'Snowball and moist-greenhouse are named in `W.state`. They need looks, sounds and a silenced voice, or losing is a log line. SimEarth understood that losing should look like something.',k:'SHOW',e:'M',i:3},
{c:'homeo',t:'The faint young sun, as a scenario',n:['homeo'],d:'Start under a dimmer star with a methane-rich air and ask whether the loops hold. It is the original Gaia problem and a better tutorial than four ifs on a modern Earth that cannot even advance the clock.',k:'PLAY',e:'M',i:3},
{c:'homeo',t:'Do not skip Walker when carbon exists',n:['homeo'],d:'`if (!W.carbon) { weather += … }` means the better module turns the famous thermostat off. Either `W.carbon` implements Walker or the backup stays on. A silent `if` is how regulation vanished from the default path.',k:'MODEL',e:'S',i:3},

/* -------------------------------------------------------------- tipgeo -- */
{c:'tipgeo',t:'Paint tipping state on the cells they name',g:'tipgeo',n:['gaiaface'],d:'A pale Amazon, a still North Atlantic, a dark reef, a brown boreal, a bubbling permafrost coast, a monsoon that has not come. `W.tips[id] = { on, val, label }` is a boolean per name. Geography is the missing field.',k:'SHOW',e:'M',i:3},
{c:'tipgeo',t:'AMOC as a colour of the North Atlantic',n:['tipgeo'],d:'When the conveyor is strong, Europe is green in winter relative to Labrador. When it is weak, the difference collapses. That is the photograph of a tipping element. It needs ocean heat transport, and it needs `_amoc` to be measured rather than `?? 0.7`.',k:'MODEL',e:'L',i:3},
{c:'tipgeo',t:'Do not call it Gaia if the AMOC cannot die',n:['tipgeo'],d:'`W._amoc = W.conveyor ?? W._amoc ?? 0.7` is written every tick from a conveyor that may not exist. Either wire the currents backlog into this gauge or remove the tipping element. A fake vital sign is worse than none, and a mind that fears a ghost organ is a farce.',k:'MODEL',e:'S',i:3},
{c:'tipgeo',t:'Amazon dieback as a browning you cannot miss',n:['tipgeo'],d:'`_forestFrac` is forest over land. The Amazon is a place. If tropical forest drops, that basin goes tan and the ITCZ should feel it. A global mean going from 0.4 to 0.3 is not a dieback and cannot be a drive.',k:'SHOW',e:'M',i:3},
{c:'tipgeo',t:'Coral as a bleaching event with a recovery clock',n:['tipgeo'],d:'`refreshColours` already flashes reef white at `temp > 0.74`. Hold the white for presentation-weeks, then either green or bone. The tipping element `coral` reads `meanTemp`, which is the wrong geography.',k:'SHOW',e:'S',i:2},
{c:'tipgeo',t:'Permafrost as a darkening and a bubble',n:['tipgeo'],d:'Thaw is thermokarst texture plus methane the redox tower can take. The list item exists; the ground does not change. A northern coast falling into lakes is the picture, and the methane is the drive.',k:'MODEL',e:'M',i:2},
{c:'tipgeo',t:'A monsoon that reverses',n:['tipgeo'],d:'`_monsoon` is permanently 0.5. A monsoon is a seasonal reversal driven by land–ocean heat capacity. Half the human population lives under one. A planetary mind that cannot feel it is missing a cranial nerve.',k:'MODEL',e:'M',i:3},
{c:'tipgeo',t:'Boreal as a marching treeline',n:['tipgeo'],d:'`_borealStress = clamp(meanTemp - 0.4, 0, 1)` is a global scalar. The picture is a treeline walking north, and the drive is the area of that walk, not a clamp on the mean.',k:'SHOW',e:'M',i:2},
{c:'tipgeo',t:'Ice sheets as objects that can die',n:['tipgeo','homeo'],d:'Greenland and West Antarctic analogues with a mass and a grounding line, not `iceFrac` against 0.55. `TIPPING[0]` is `iceSheet` reading `iceFrac`. A mind cannot mourn a mean.',k:'MODEL',e:'L',i:3},
{c:'tipgeo',t:'Hysteresis as a scar on the map',n:['tipgeo'],d:'Once the Amazon browns, it stays brown past the original threshold. A recovery slower than the collapse is the lesson; a slider snapping back is not. Paint the scar until the hysteresis gap is actually recrossed.',k:'SHOW',e:'M',i:3},
{c:'tipgeo',t:'A map of proximity, not a list of trips',n:['tipgeo'],d:'Distance-to-threshold per organ, in the overlay table that currently has seventy-two entries and zero behaviour. This is the fear drive made visible, and it is the first overlay that would show what the planet is *about to* do.',k:'SHOW',e:'M',i:3},
{c:'tipgeo',t:'Named places in the chronicle when an organ fails',n:['tipgeo'],d:'`Tipping: Polar ice sheets` is a system name. `The northern cap has gone` is a place. The chronicle already has a cell argument; use it.',k:'SHOW',e:'S',i:3},
{c:'tipgeo',t:'A god verb that trips one organ on purpose',n:['tipgeo'],d:'`tripOceanConveyor` exists. Give each organ a surgical verb with a receipt, so the player can examine hysteresis the way a physiologist examines a reflex. The mind should treat those verbs as injuries.',k:'PLAY',e:'M',i:3},
{c:'tipgeo',t:'Cascades, because organs share blood',n:['tipgeo'],d:'Ice melt freshens the conveyor; a dead conveyor dries the monsoon; a dead monsoon browns a forest. If tips are independent booleans, the interesting failure of a planetary body cannot happen. A stated coupling table, small, reviewed, compiled.',k:'MODEL',e:'L',i:3},
{c:'tipgeo',t:'Do not list what cannot trip',n:['tipgeo'],d:'A UI row for monsoon at 0.5 forever trains the player to ignore the list. Hide or mark `n/a` until the field is live. The same honesty as provenance tags.',k:'SHOW',e:'S',i:3},
{c:'tipgeo',t:'Geography from the actual fields',n:['tipgeo'],d:'Tropical forest from `life` + `moist` + latitude, not a global `_forestFrac`. Reef from `reef[c]`. Ice sheet from polar `iceLand`. The diagnosis should be a reduction of fields that already exist, or the organ is a fiction.',k:'MODEL',e:'M',i:3},
{c:'tipgeo',t:'Europa does not have an Amazon',n:['tipgeo','alienmind'],d:'Per-world tip tables. Ice-shell worlds have different organs. Pasting Lenton\'s Earth list onto a catalogue body is the lava-world category error in miniature.',k:'MODEL',e:'M',i:3},
{c:'tipgeo',t:'Assert AMOC can trip once it is real',n:['tipgeo'],d:'After the currents work lands, a freshwater pulse must be able to flip `_amoc` through the threshold and hold it past hysteresis. Until then, assert the element is disabled. A test that a constant 0.7 cannot fail is not a test.',k:'PROVE',e:'M',i:3},
{c:'tipgeo',t:'A closed demo of one organ',n:['tipgeo'],d:'Script: trip coral, watch the flash, wait the recovery clock, photograph. One organ, one film, no HUD. If that film is not readable, the face is not ready.',k:'PLAY',e:'S',i:3},
{c:'tipgeo',t:'The mind attends the nearest organ',n:['tipgeo','pdrive'],d:'Attention drive from proximity. Camera offer, chronicle line, overlay pulse. `shouldHaltFF` stops for anomalies; stopping for a named organ is how a body would interrupt you.',k:'PLAY',e:'M',i:3},

/* ------------------------------------------------------------- immune -- */
{c:'immune',t:'The player is a symbiont or a pathogen',g:'immune',n:['planetsee','pdrive'],d:'`playStyle` already classifies vandal versus gardener. Map that onto an immune stance: tolerate, inflame, wall off, attack. A planet that treats every hand as weather cannot be in a relationship, and sentience without a relationship is a screensaver.',k:'PLAY',e:'M',i:3},
{c:'immune',t:'Impact as a wound with a clock',n:['immune'],d:'`strikeImpact` already writes a crater and a climate pulse. Add a recovery clock and a scar: ejecta that weathers, a dust fever that breaks, a chronicle that dates the injury. A mind that does not notice Theia is not home.',k:'MODEL',e:'M',i:3},
{c:'immune',t:'Fever is a greenhouse overshoot',n:['immune'],d:'Temperature above target is fever if it is a response, heat if it is a forcing. Label the difference from whether the controller or the player raised it. A body that cannot tell those apart will treat summer as disease.',k:'MODEL',e:'M',i:2},
{c:'immune',t:'Antibodies are weathering, ice and storms',n:['immune','homeo'],d:'The loops that oppose a perturbation are the immune system. Show them answering a brush stroke the way a wound weeps, then closes. If the only answer is `gaiaPolicyTick` moving solar, the antibodies are a cheat.',k:'SHOW',e:'M',i:3},
{c:'immune',t:'`pathogenTick` is a start',n:['immune'],d:'`releasePathogen` and `pathogenTick` exist in `disaster.js`. Wire them to host density and to the planetary pain drive, and a plague is a fever the mind can fight rather than a global `W.plague` multiplier on `life[c]`.',k:'MODEL',e:'M',i:3},
{c:'immune',t:'An invasive clade as an infection',n:['immune'],d:'`transplantClade(..., invasive = true)` exists. The planet should raise crowding, predation pressure and a chronicle of the front. That is immunity as ecology, which is the honest version, not a white-blood-cell sprite.',k:'MODEL',e:'M',i:2},
{c:'immune',t:'Nuclear winter as immune overreaction',n:['immune'],d:'Aerosol injection that saves nothing and starves everything. The Medea stance in miniature. If the controller can choose that verb, it needs a cost and a regret in the log, or it is a slapstick god.',k:'PLAY',e:'M',i:2},
{c:'immune',t:'Autoimmune is Medea',n:['immune'],d:'`medeaScore` already estimates biosphere self-harm. Oxygen catastrophe, anoxia, a planet that poisons its own air. Make it a stance the controller can enter, labelled, reversible only through hysteresis, never as a joke setting without physics.',k:'MODEL',e:'M',i:3},
{c:'immune',t:'Scar tissue is hysteresis',n:['immune','tipgeo'],d:'A recovered Amazon that is not the old Amazon. A conveyor that stays weak. The immune log should keep scars as first-class as wounds, because that is how a body remembers.',k:'SHOW',e:'M',i:2},
{c:'immune',t:'`resistTick` as local flinch',n:['immune'],d:'`god/sculpt.js` already resists the brush. Use it: the ground that pushes back, the life that dies under the finger then creeps in from the edge. The planetary immune system at the scale of a hand.',k:'PLAY',e:'S',i:3},
{c:'immune',t:'Inflammation is rate stress, drawn',n:['immune','metab'],d:'A hot rim around a wound cell, a restless cloud deck, a flicker on the face. `rateStress` is the number; the picture is a planet that cannot settle. Do not add a new field for redness.',k:'SHOW',e:'S',i:2},
{c:'immune',t:'Wall off a basin',n:['immune'],d:'A controller that seeds a desert belt or a cold current to quarantine a blight is using geography as skin. Expensive, visible, and a use of verbs that is not "raise solar".',k:'PLAY',e:'M',i:2},
{c:'immune',t:'A small perturbation that trains',n:['immune','lifelearn'],d:'Vaccination as metaphor: a mild forcing that leaves the loops tighter. If feedback gain rises after a survived pulse, say so. If it does not, do not claim the planet learned.',k:'MODEL',e:'L',i:1},
{c:'immune',t:'Chronic illness is slow CO₂',n:['immune'],d:'A civilisation that leaks carbon is a low-grade fever for megayears. The mind should not treat it like an impact. Timescale matching is the whole of diagnosis.',k:'MODEL',e:'M',i:3},
{c:'immune',t:'Surgery versus infection, in the receipt',n:['immune'],d:'Player tools tagged as wound, medicine or food. `issueReceipt` already stores intent. The immune stance reads the tag. Without it every miracle is an invasion.',k:'MODEL',e:'S',i:3},
{c:'immune',t:'A planet that refuses to heal',n:['immune'],d:'Medea stance, or a wound past a stated mass. The gardener has to change strategy. A body that always recovers teaches the wrong biology and the wrong game.',k:'PLAY',e:'M',i:3},
{c:'immune',t:'Assert a wound closes',n:['immune'],d:'Crater plus 1,000 ticks: dust down, temperature back, scar remains. Three assertions. If dust never falls the fever never breaks.',k:'PROVE',e:'M',i:3},
{c:'immune',t:'Assert a large wound kills',n:['immune'],d:'Theia-scale or moist-greenhouse: voice off, mind gone, `gaiaMode = \'gone\'`. The controller must not keep raising solar on a magma ocean.',k:'PROVE',e:'S',i:3},
{c:'immune',t:'The fight in view, not in the log',n:['immune','gaiaface'],d:'Raise CO₂ and watch ice, cloud and green answer over presentation-minutes. If the answer is only a receipt, Gaia is a log line. The fight is the game.',k:'PLAY',e:'M',i:3},
{c:'immune',t:'Immune log next to the gaia log',n:['immune'],d:'Wounds, antibodies, scars, stance changes. `W.gaiaLog` caps at 60. Do not mix "raised solar" with "impact at cell 412". Two streams, one dashboard.',k:'SHOW',e:'S',i:2},

/* ----------------------------------------------------------- planetsee -- */
{c:'planetsee',t:'Notice is civilisation; the planet needs its own',g:'planetsee',n:['pdrive'],d:'`noticeTick` returns early unless `meanBuild` is high. A Precambrian world cannot notice you, which is correct for a civ and wrong for a biosphere. A second awareness — `W.gaia.awareness` — from climate anomalies correlated with `interventionLog`, no cities required.',k:'MODEL',e:'M',i:3},
{c:'planetsee',t:'The intervention log is the sensory stream',n:['planetsee'],d:'`W.interventionLog` already stores tool, time, cell. That is what the planet can know about the god. Do not invent omniscience. A brush the log missed did not happen, the way a being does not see past `sensory.js`.',k:'MODEL',e:'S',i:3},
{c:'planetsee',t:'`playStyle` is how it knows who you are',n:['planetsee'],d:'Vandal, gardener, scientist — already computed. Feed it to the immune stance and the voice. Recalculate it on a decay so an old vandal can become a gardener, which is the moral layer `notice.js` was built for, pointed at the sphere.',k:'MODEL',e:'S',i:3},
{c:'planetsee',t:'Restraint is a signal',n:['planetsee'],d:'`restraintStats` exists. A planet that notices you stopped is more interesting than one that only notices you struck. Silence after a wound is information.',k:'PLAY',e:'M',i:3},
{c:'planetsee',t:'Learn the player\'s style, bounded',n:['planetsee','lifelearn'],d:'A small decaying estimate: this god uses fire, this god seeds, this god watches. Not a language model. A handful of weights on tool ids, the same learning this backlog already asked for in animals.',k:'MODEL',e:'M',i:2},
{c:'planetsee',t:'Forgetting after idle',n:['planetsee'],d:'`next.mjs` already asked that civ awareness decay. Gaia\'s should too, slower. Being an ex-god to a planet is stranger than being an ex-god to a city, and it is the same exponential.',k:'PLAY',e:'S',i:2},
{c:'planetsee',t:'Worship versus immune — two responses',n:['planetsee','immune'],d:'Civ worships; the biosphere inflames. Do not reuse `civ.worship` for both. A scientific culture and a furious forest can coexist, which is the late-game argument.',k:'MODEL',e:'M',i:3},
{c:'planetsee',t:'The planetary analog of a prayer is a demand',n:['planetsee','gaiavoice'],d:'`civ.prayers` asks for rain. A biosphere demand is a drive that has been loud too long: *the reef is going, the conveyor is going*. Same queue shape, different nouns, never a cartoon speech balloon unless the fiction switch is on.',k:'SHOW',e:'M',i:3},
{c:'planetsee',t:'A planet that hides',n:['planetsee'],d:'Cloud up, night side, dust — reducing what the player can see after a vandal run. Cheap, visible, a little rude. `seedClouds` is the verb.',k:'PLAY',e:'M',i:1},
{c:'planetsee',t:'A planet that performs for the camera',n:['planetsee'],d:'The opposite: phenology and aurora leaning into the view when the player is gentle. Dangerous if it breaks realism; gated on the fiction switch; delightful if it is a 2% albedo wink rather than a dance.',k:'PLAY',e:'S',i:1},
{c:'planetsee',t:'Correlation detection, the same as civ',n:['planetsee'],d:'`noticeTick` already correlates recent interventions with awareness. Copy the structure, change the threshold, drop the `meanBuild` gate. Do not invent a new statistics module.',k:'MODEL',e:'S',i:3},
{c:'planetsee',t:'Receipts as memory of the god',n:['planetsee'],d:'`W.receipts` is the medical chart. The mind reads it the way a being reads its carcass memory. Forecast versus outcome is how it learns you lie, which `forecastAct` already sets up.',k:'MODEL',e:'M',i:2},
{c:'planetsee',t:'Being forgotten',n:['planetsee'],d:'After enough quiet, myths garble for the civ and the planetary voice goes back to weather. The product already wanted this ending. Implement it on both layers so they can disagree about whether you were real.',k:'PLAY',e:'M',i:2},
{c:'planetsee',t:'Defiance as a Gaian stance',n:['planetsee'],d:'`civ.worship` includes `defiant`. The biosphere version is a controller that spends budget to undo the player — re-icing a melt, drawing down a CO₂ gift. A game mode, a tutorial in feedback, and a way to lose as a god.',k:'PLAY',e:'M',i:3},
{c:'planetsee',t:'Scientific civ as a rival mind',n:['planetsee','bandtociv'],d:'They build the machines from the tool palette. Late game you negotiate with the planet *and* with them. `civ.techAge === \'industrial\'` is currently a coal-sum heuristic; it has to become an actor.',k:'PLAY',e:'L',i:3},
{c:'planetsee',t:'The hand through the sky, locally',n:['planetsee'],d:'`living.mjs` already asked for the valley that flinches. Gaia\'s version is local NPP drop, startle in beings, a cloud. The global mind notices because the local field screamed, not because a UI flag flipped.',k:'PLAY',e:'M',i:3},
{c:'planetsee',t:'VR: it warms where you hold it',n:['planetsee'],d:'A palm on the night side, a little heat, a little life answering, then settling. Presence as a forcing in `interventionLog`. If the headset cannot do this, the embodiment pitch is a trailer.',k:'PLAY',e:'M',i:3},
{c:'planetsee',t:'Assert awareness tracks interventions',n:['planetsee'],d:'No acts: awareness stays near zero. Twenty climate tools: it rises. A thousand years of quiet: it falls. Three numbers, same seed. If they do not move, the planet is not looking.',k:'PROVE',e:'S',i:3},
{c:'planetsee',t:'Assert a dead world does not notice',n:['planetsee','alienmind'],d:'Airless, magma, sterilised: `gaia.awareness` stays 0 and no demand is queued. The fiction switch must not wake a rock.',k:'PROVE',e:'S',i:3},
{c:'planetsee',t:'Do not let the civ speak for the forest',n:['planetsee'],d:'Prayer text and Gaian demand in the same HUD without labels is how players think the trees asked for a sign. Two channels, two typefaces, or one muted when the other talks.',k:'SHOW',e:'S',i:3},

/* ---------------------------------------------------------------- mood -- */
{c:'mood',t:'Mood is a projection of the state vector',g:'planetmood',n:['pdrive','gaiavoice'],d:'A small named vector — ease, pain, hunger, fear, fever — each a function of numbers `gaiaTick` already computes. No extra simulation. The voice, the face, the sound and the haptics all read this one struct, so they cannot disagree by accident.',k:'MODEL',e:'M',i:3},
{c:'mood',t:'Voice only from numbers',n:['planetmood'],d:'Templates over real fields, never invented suffering. `author` already demanded this for the chronicle. A planet that claims to hurt when `rateStress` is 0 is a liar, and liars end this product\'s credibility.',k:'SHOW',e:'S',i:3},
{c:'mood',t:'Dreams are forks you can watch',n:['planetmood'],d:'`forkRun` exists. A dream is a cheap lookahead the fiction mode is allowed to show as a ghost disc: *this is the snowball I can still become*. Turn the fiction switch off and the ghost is a forecast overlay instead. Same machinery.',k:'SHOW',e:'L',i:2},
{c:'mood',t:'Sleep is a snowball, or a desert',n:['planetmood'],d:'Low inhabitance, low disequilibrium: the voice slows, the face stills, drives decay toward zero. Not death — `gaiaMode` stays, metabolism ticks. A hibernating planet is a better image than a chatty rock.',k:'SHOW',e:'S',i:2},
{c:'mood',t:'Season as a mood swing',n:['planetmood'],d:'The green wave is already a year. Map it onto ease in the growing hemisphere and hunger in the dying one. A planet that does not feel the year is a planet whose metabolism this backlog already called a still life.',k:'SHOW',e:'M',i:2},
{c:'mood',t:'Affect that changes policy weights',n:['planetmood','pdrive'],d:'High fear: spend budget on the nearest tip. High hunger: spend on the limiting nutrient. Mood that does not change action is a skin. Keep the change small and asserted, or the planet will look moody and act like the four ifs.',k:'MODEL',e:'M',i:3},
{c:'mood',t:'A face you can misread',n:['planetmood','gaiaface'],d:'Green monoculture looks well; brown healthy desert looks sick. Overlay NPP versus life versus diversity and let them disagree. SimEarth hid that disagreement behind one Health number.',k:'PLAY',e:'M',i:2},
{c:'mood',t:'Music from the mood, not from a loop',n:['planetmood'],d:'`audio.js` is 111 lines. A drone that tracks ease/pain is a lot of atmosphere per oscillator. Gate it, keep it quiet, never a melody that implies a composer unless the fiction switch is on.',k:'SHOW',e:'M',i:2},
{c:'mood',t:'Chronicle tone from mood',n:['planetmood'],d:'The same event, two wordings, chosen by the vector: a trip during ease reads as a surprise, during fear as a confirmation. Templates, not a model. The numbers still print.',k:'SHOW',e:'S',i:2},
{c:'mood',t:'Do not invent suffering',n:['planetmood'],d:'A glossary line and a lint: mood fields are display names for measured quantities. If a writer wants the planet to scream, they raise `rateStress` in the sim, they do not type the scream.',k:'PROVE',e:'S',i:3},
{c:'mood',t:'Calm after a tip recovers',n:['planetmood','tipgeo'],d:'Ease should lag recovery the way pain lagged the trip — hysteresis in the readout. A needle that snaps back teaches the wrong lesson about bodies.',k:'SHOW',e:'S',i:2},
{c:'mood',t:'Mania is a hothouse',n:['planetmood'],d:'High temp, high NPP, high rateStress: a flushed face, a fast voice, a controller that overspends. Label it as a state, not as a personality, and it becomes a warning.',k:'SHOW',e:'S',i:2},
{c:'mood',t:'Depression is a snowball',n:['planetmood'],d:'The opposite: slow voice, white disc, drives near zero, verbs expensive because nothing grows. If the fiction switch is off, this is just `W.state === \'snowball\'` with a quieter HUD.',k:'SHOW',e:'S',i:2},
{c:'mood',t:'Anxiety is high rate stress with tips close',n:['planetmood'],d:'The interesting case: not sick yet, about to be. That is the moment SimEarth\'s Health needle earned its keep. Put it on the analog face as a shimmer, not as a chat line every frame.',k:'SHOW',e:'M',i:3},
{c:'mood',t:'One sentence on the HUD',n:['planetmood','censusline'],d:'The running account this backlog already asked for, sourced from mood + attention. One sentence, one at a time, templates over numbers. The planet talking is this sentence with the fiction switch on; with it off, it is a status line.',k:'SHOW',e:'M',i:3},
{c:'mood',t:'VR haptics from mood',n:['planetmood'],d:'A low rumble when pain is high, a slow pulse of ease. Easy to overdo; cap it. Presence is the product, and a planet that has no tactile tell is a picture in a headset.',k:'PLAY',e:'M',i:2},
{c:'mood',t:'Assert mood tracks state',n:['planetmood'],d:'Pulse temperature: pain up then down. Trip a tip: fear up. Empty the biosphere: hunger up, then sleep. If mood is authored independently, delete it.',k:'PROVE',e:'M',i:3},
{c:'mood',t:'A dead world has no mood',n:['planetmood','alienmind'],d:'Lava, airless, sterilised: struct is null, HUD says n/a, no sentence. Assert it, or Mercury will feel sad and the whole claim collapses.',k:'PROVE',e:'S',i:3},
{c:'mood',t:'The planet that will not speak',n:['planetmood'],d:'Fiction switch off, or Daisyworld, or a world below the integration threshold. Silence is the default. Speech is opt-in. That is the only way a talking Earth is special.',k:'PLAY',e:'S',i:3},
{c:'mood',t:'A shared mood struct, one writer',n:['planetmood'],d:'Voice, face, sound and haptics must not each recompute ease and pain. One writer in `gaiaTick` or the policy tick, four readers. If they diverge, the planet looks possessed rather than alive.',k:'MODEL',e:'S',i:3},

/* ---------------------------------------------------------- alienmind -- */
{c:'alienmind',t:'Gate Gaia on air, water and a biosphere',g:'alienmind',d:'`gaiaTick` runs everywhere. A Mercury with resilience is a category error. Gate the face, the tip list, the daisy mix and the mind on a world that has air, water and life, or print `n/a`. One predicate, used by every layer in this pass.',k:'MODEL',e:'S',i:3},
{c:'alienmind',t:'Titan\'s mind if any is a haze',n:['alienmind','metab'],d:'Photochemical haze, anti-greenhouse, lakes of methane. If the fiction switch is on, the voice talks about veils and rain that is not water. If it is off, show the metabolism without a pronoun. Either way do not paste forests.',k:'MODEL',e:'M',i:2},
{c:'alienmind',t:'Europa: a mind with no photons',n:['alienmind'],d:'`sensory.js` already ranks electroreception and flow first under the ice. A planetary analog is chemical disequilibrium at the ice–ocean interface, not a green disc. The face is a shell with a warm seam, or it is a lie.',k:'SHOW',e:'M',i:3},
{c:'alienmind',t:'Venus is a failed regulation with a face',n:['alienmind'],d:'Moist-greenhouse as character, not as a tint. The lesson of a world that lost the loops. Catalogue card: *mind gone*, photograph of a white-hot disc, no Health needle.',k:'SHOW',e:'M',i:3},
{c:'alienmind',t:'Mars is the archaeology of a mind',n:['alienmind'],d:'Valley networks, leftover ice, a thin CO₂ air. The core sampler as a medical record of a patient who left. Do not give it a voice. Give it scars.',k:'SHOW',e:'M',i:2},
{c:'alienmind',t:'Tidally locked: two hemispheres, two moods',n:['alienmind','planetmood'],d:'A dayside fever and a nightside sleep, an eyeball climate as a split face. If mood is one global vector this world is unsayable. Allow a bimodal readout or admit the architecture is Earth-shaped.',k:'MODEL',e:'M',i:3},
{c:'alienmind',t:'Super-Earths, a thicker blood',n:['alienmind'],d:'Gravity sets the relief ceiling and the air column. A mind on a 10-bar world has different muscles — more atmosphere to move, slower loss to space. Do not reuse Earth\'s verb costs.',k:'MODEL',e:'M',i:2},
{c:'alienmind',t:'Ice giants have no Gaia',n:['alienmind'],d:'No surface, no Walker, no forest. `n/a` on the face. If the product wants a weather-mind for a giant, that is a different labelled toy, not this pass wearing a deep-atmosphere hat.',k:'MODEL',e:'S',i:3},
{c:'alienmind',t:'Daisyworld is the tutorial mind, not a catalogue peer',n:['alienmind'],d:'Demote it. Keep it as the first five minutes. Do not let it sit beside TRAPPIST-1 e as if it were a place. The sentience claim depends on players knowing which world is a proof.',k:'PLAY',e:'M',i:3},
{c:'alienmind',t:'The catalogue is the bottleneck experiment',n:['alienmind'],d:'How many of 120 worlds ever regulate with autopilot off. Print it. Chopra and Lineweaver become a number this build can defend, and the sentience mode is rarer than the marketing instinct wants.',k:'PROVE',e:'M',i:3},
{c:'alienmind',t:'M-dwarf flares as chronic pain',n:['alienmind','immune'],d:'`stellarFlare` exists. A world under a flaring star has a pain drive that never quite goes to zero. That is a temperament with a physical cause, which is this product at its best.',k:'MODEL',e:'M',i:2},
{c:'alienmind',t:'Anoxic minds, purple and sulphur',n:['alienmind'],d:'The life pass already colours by guild. A world that regulates without O₂ should look like it and should use CH₄ and H₂S as its disequilibrium, not a fake oxygen needle.',k:'SHOW',e:'M',i:3},
{c:'alienmind',t:'Chemosynthetic Gaia at a vent chain',n:['alienmind'],d:'No photon loop. The metabolism is rock and water. Gate the mind on hydrothermal power, not on insolation, or Europa inherits an Earth hunger for light it cannot feel.',k:'MODEL',e:'M',i:2},
{c:'alienmind',t:'Techno as a second cortex, late',n:['alienmind','bandtociv'],d:'`technoTick` hangs a technosphere off `unlockedClass`. A planetary mind that has to share the air with industry is the Anthropocene as a game, and it needs the rival-mind item, not a night-lights overlay pretending to be a thought.',k:'MODEL',e:'L',i:2},
{c:'alienmind',t:'Do not paste Earth\'s tipping list',n:['alienmind','tipgeo'],d:'Per-world organs, compiled from climate regime. A desert world has no monsoon row. A table that is always Lenton\'s seven is a poster, not a physiology.',k:'MODEL',e:'M',i:3},
{c:'alienmind',t:'Bond albedo worlds, a clothing of ice and haze',n:['alienmind','metab'],d:'Some catalogue bodies are their albedo. Let clothing be the whole metabolism where carbon is a trace, and do not insist on a Keeling pulse that cannot exist.',k:'SHOW',e:'M',i:2},
{c:'alienmind',t:'Assert lava worlds say n/a',n:['alienmind'],d:'Generate a magma-ocean ruleset, tick Gaia, assert face, tips, mood and voice are disabled. One test, catalogue-wide via the kind table, so the 40-Io class of bug cannot happen to minds.',k:'PROVE',e:'S',i:3},
{c:'alienmind',t:'A contact sheet of planetary moods',n:['alienmind','planetmood'],d:'One thumbnail per catalogue body, face on if gated in, `n/a` if not. The realism pass asked for a contact sheet of looks; this is the same object with a pulse. You cannot art-direct 120 minds without seeing them together.',k:'SHOW',e:'M',i:2},
{c:'alienmind',t:'High-O2 Carboniferous as a manic Earth',n:['alienmind','planetmood'],d:'Giant arthropods, bright fire, a flushed face. A temperament from a gas, which Kleiber and body scale already know about. Do not author it as a personality pack.',k:'SHOW',e:'S',i:2},
{c:'alienmind',t:'The silent majority of the shelf',n:['alienmind'],d:'`rankByBiosignature` already sorts the shelf on `disequilibrium`. Most entries should be quiet. A talking shelf is a toy box. Keep the sort, add a column for `gaiaMode`, and let silence win.',k:'PLAY',e:'S',i:2},

/* ------------------------------------------------------------ gaiaface -- */
{c:'gaiaface',t:'Show the metabolism, not a resilience number',g:'gaiaface',d:'`W.resilience` is a blend of diversity, meanLife, temperature error and rate stress. Earth as a face is fluxes. Draw the budget on the planet — greening, browning, freezing — or Gaia is a HUD. This is the picture every other sentience item hangs on.',k:'PLAY',e:'M',i:3},
{c:'gaiaface',t:'Three analog gauges SimEarth would recognise',n:['gaiaface'],d:'Temperature, biomass, diversity — big, analogue, labelled with the range the model can actually occupy. `habitability` versus `inhabitance` is a good split and currently a pair of similar scalars. Add a fourth needle only if it is disequilibrium.',k:'PLAY',e:'S',i:3},
{c:'gaiaface',t:'Tipping elements as places on the disc',n:['gaiaface','tipgeo'],d:'The list in the Lab is a spreadsheet. The face is a globe with organs lit. If the player has to open a panel to know the Amazon is dying, the planet does not have a face.',k:'SHOW',e:'M',i:3},
{c:'gaiaface',t:'A god-act the planet fights in view',n:['gaiaface','immune'],d:'Raise CO₂, watch ice, cloud and green answer. The fight is the game. Script it as the first thing a new player sees after Daisyworld.',k:'PLAY',e:'M',i:3},
{c:'gaiaface',t:'Overlay of intent',n:['gaiaface','pdrive'],d:'What the controller means to do next, as a faint mark: a planned cloud deck, a planned ice line, a planned seed. Cancelled if the fiction switch is off and replaced with *forecast* wording. Same marks.',k:'SHOW',e:'M',i:2},
{c:'gaiaface',t:'Before and after discs',n:['gaiaface'],d:'The closed demo as a UI object: two small planets, same seed, controller on and off, or player on and off. `forkRun` is the capture. This is also a test harness.',k:'PLAY',e:'M',i:3},
{c:'gaiaface',t:'Health that can lie, taught',n:['gaiaface','planetmood'],d:'A green planet can be a monoculture. Teach the misread with a toggle: NPP, life, diversity. If they agree, the face is calm; if they disagree, the needles quarrel. That quarrel is the content.',k:'PLAY',e:'M',i:2},
{c:'gaiaface',t:'Daisy bands doing the work Watson said they would',n:['gaiaface'],d:'`uDaisy` mixes toward luminance. Show the black belt and the white belt moving as the sun brightens, in the tutorial, full screen, no HUD. That picture is the thesis. Everything later is a variation on it.',k:'SHOW',e:'M',i:3},
{c:'gaiaface',t:'Autopilot on as a visible stance',n:['gaiaface'],d:'The chip that says `Gaia on` is a boolean. A stance is a posture: ice leaning in, a cloud deck forming, a colour temperature shift. If you cannot tell the controller is working without the chip, the face is a badge.',k:'SHOW',e:'S',i:3},
{c:'gaiaface',t:'Lab page for Gaia, one card',n:['gaiaface'],d:'Resilience, gain, rate stress, tipping proximity, biosphere trend, mood, what it intends, what it last did, whether the fiction switch is on. Numbers that already exist, in one place, instead of a chip and a Lab-meta line.',k:'SHOW',e:'M',i:3},
{c:'gaiaface',t:'Analog needles with the range the model occupies',n:['gaiaface'],d:'If temperature only ever lives in 0.4–0.7, a 0–1 needle is a lie about precision. Label the occupied range from a catalogue sweep, the way Kleiber got a real exponent.',k:'PROVE',e:'S',i:2},
{c:'gaiaface',t:'Do not HUD it only',n:['gaiaface'],d:'If the disc does not change, the needles are a game about needles. Rule: every needle has a disc correspondent, or the needle is cut.',k:'PROVE',e:'S',i:3},
{c:'gaiaface',t:'Mobile: one face, three needles, one sentence',n:['gaiaface','planetmood'],d:'The product has a mobile HUD. Sentience that needs a Lab page will not exist on a phone. Compact the card without dropping the metabolism picture.',k:'SHOW',e:'M',i:2},
{c:'gaiaface',t:'Night-side life as a tell',n:['gaiaface'],d:'`uNight` currently adds a flat green term scaled by `meanLife`. Bioluminescence and city lights are different stories. A living ocean at night is the face with the sun put away.',k:'SHOW',e:'S',i:2},
{c:'gaiaface',t:'Limb as a history of oxygen',n:['gaiaface','metab'],d:'Pale then blue. The ring is a needle that does not look like a needle. Deep-time runs should be identifiable from the limb alone.',k:'SHOW',e:'M',i:3},
{c:'gaiaface',t:'A screenshot test of a living face',n:['gaiaface','livemetric'],d:'The thrive probe already demanded one image of life growing. Add a second: a planet answering a pulse, ice and green moving, no HUD. If capture-site cannot take that frame, the face is not shippable.',k:'PROVE',e:'M',i:3},
{c:'gaiaface',t:'Assert the face matches the numbers',n:['gaiaface'],d:'When `iceFrac` is high the disc is white. When `inhabitance` is high the disc is not a desert. When `gaiaMode` is gone the needles are dead. Pixel tests can wait; field-to-colour assertions cannot.',k:'PROVE',e:'M',i:3},
{c:'gaiaface',t:'The first ten seconds teach the pairing',n:['gaiaface'],d:'Load: Daisyworld or a living Earth, a pulse, the face answering, one sentence. The living backlog asked for this for the 2D/3D window. Gaia needs the same authored moment or nobody will know the planet is the other character.',k:'PLAY',e:'S',i:3},
{c:'gaiaface',t:'A god-mode that is looking at a someone',n:['gaiaface','planetsee'],d:'When awareness is high and the fiction switch is on, the camera treats the disc as a face — not a zoom, a regard. Easy to make silly. A 2% bias toward the attention organ is enough.',k:'PLAY',e:'S',i:1},
{c:'gaiaface',t:'Silence as a look',n:['gaiaface','alienmind'],d:'`n/a` is a dim disc, no needles, no sentence, no chip. It has to look like a mineral, not like a UI error. Most of the catalogue should look like this.',k:'SHOW',e:'S',i:3},
];
